        self.poll_peek_mut(cx).map(|opt| opt.map(|item| &*item))
    }

    /// Consume and return the next item if the predicate returns `true`.
    pub async fn next_if<F>(&mut self, func: F) -> Option<T::Item>
    where
        T: Unpin,
        F: FnOnce(&T::Item) -> bool,
    {
        match self.peek().await {
            Some(item) if func(item) => self.next().await,
            _ => None,
        }
    }

    /// Consume and return the next item if it equals `expected`.
    pub async fn next_if_eq<U>(&mut self, expected: &U) -> Option<T::Item>
    where
        T: Unpin,
        U: ?Sized,
        T::Item: PartialEq<U>,
    {
        self.next_if(|item| item == expected).await
    }
}

