    #[cfg(feature = "arbitrary_precision")]
    /// Returns the `&str` representation of the `Number`.
    /// ```
    /// # use serde_json::Number;
    /// for value in [
    ///     "7",
    ///     "12.34",
    ///     "34e-56789",
