/// def implementation(): ...
///
/// def test_use(public_name): ...
/// ```
pub(crate) fn explicit_fixture_name_at_offset<'db>(
    model: &SemanticModel<'db>,
    module: &ParsedModuleRef,
    offset: TextSize,
) -> Option<FixtureReferenceTarget<'db>> {
    let covering = covering_node(module.syntax().into(), TextRange::empty(offset));
    let function = covering.ancestors().find_map(|ancestor| match ancestor {
        AnyNodeRef::StmtFunctionDef(function) => Some(function),
        _ => None,
    })?;
    let definition = ty_python_core::semantic_index(model.db(), model.program_file())
        .expect_single_definition(function);
    let exposures = fixture_exposures_for_definition(model.db(), definition);

    FixtureReferenceTarget::from_exposures(
        model.db(),
        exposures.iter().filter(|exposure| {
            matches!(
                exposure.name_source(model.db()),
                FixtureNameSource::Explicit {
                    declaration: Some(declaration), ..
                } if declaration.file() == model.file()
                    && declaration.range().contains_inclusive(offset)
            )
        }),
    )
}

/// Finds references starting from an explicit fixture-name declaration.
pub(crate) fn references_for_explicit_fixture_name(
    db: &dyn Db,
    file: ProgramFile<'_>,
    target: FixtureReferenceTarget<'_>,
    mode: ReferencesMode,
) -> Option<Vec<ReferenceTarget>> {
    let search = LocalReferenceSearch {
        target_text: target.name.to_string(),
        target_definitions: Definitions::new(Vec::new()),
        import_alias_resolution: ImportAliasResolution::PreserveAliases,
        fixture_resolution: Some(target.resolution),
    };
    references_for_search(db, file, &search, mode, false, false)
}

