        _: &'tcx Body<'_>,
        _: Span,
        def_id: LocalDefId,
    ) {
        // Building MIR for `fn`s with unsatisfiable clauses results in ICE.
        if fn_has_unsatisfiable_clauses(cx, def_id.to_def_id()) {
            return;
        }

